local ok, res = pcall(function() local o = {} local units = bm:get_player_army():units() for i = 1, units:count() do local u = units:item(i) local p = u:position() o[#o + 1] = i .. " " .. u:name() .. " " .. u:type() .. " " .. tostring(u:unit_class()) .. " range " .. u:missile_range() .. " ammo " .. u:ammo_left() .. " men " .. u:number_of_men_alive() .. (u:is_commanding_unit() and " GENERAL" or "") .. " at " .. math.floor(p:get_x()) .. "," .. math.floor(p:get_z()) .. " brg " .. math.floor(u:bearing()) end local F = _G.DERPY_FOLLOW return {units = table.concat(o, " | "), on = F and F.on, ctl = F and F.unit_name} end) if ok then return res end return "ERR " .. tostring(res)
